// Embedded brand fonts for 100% reliable social image rendering across runtimes
function base64ToArrayBuffer(base64: string): ArrayBuffer {
  if (typeof Buffer !== "undefined") {
    const buf = Buffer.from(base64, "base64");
    return buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength);
  }
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes.buffer;
}

const NEWSREADER_MEDIUM_BASE64 = "";
const NEWSREADER_ITALIC_BASE64 = "";
const MANROPE_MEDIUM_BASE64 = "";

export function getOgFonts() {
  return [
    {
      name: "Newsreader",
      data: base64ToArrayBuffer(NEWSREADER_MEDIUM_BASE64),
      style: "normal" as const,
      weight: 500 as const,
    },
    {
      name: "Newsreader",
      data: base64ToArrayBuffer(NEWSREADER_ITALIC_BASE64),
      style: "italic" as const,
      weight: 400 as const,
    },
    {
      name: "Manrope",
      data: base64ToArrayBuffer(MANROPE_MEDIUM_BASE64),
      style: "normal" as const,
      weight: 500 as const,
    },
  ];
}
